func safeThemeImageURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}

	// Allow site-relative media and static paths.
	if strings.HasPrefix(raw, "/uploads/") || strings.HasPrefix(raw, "/static/") {
		return raw
	}

	// Allow bundled theme static assets: /themes/{theme}/static/...
	if strings.HasPrefix(raw, "/themes/") && strings.Contains(raw, "/static/") {
		return raw
	}

	parsed, err := url.Parse(raw)
	if err != nil {
		return ""
	}
	if parsed.Scheme == "http" || parsed.Scheme == "https" {
		return raw
	}

	return ""
}

